function date(y){return y<0?`${Math.abs(y).toLocaleString('sv-SE')} f.Kr.`:y===2026?'2026 · idag':`${y} e.Kr.`}
function visible(){return buildings.filter(b=>year>=b.start&&year<=(b.end??9999)&&(!b.recon||$('#layerRecon').checked)&&(!(b.category==='marine')||$('#layerMarine').checked)&&(b.recordType!=='marine'||explorer.available(b,year)))}
function symbol(type,recon=false,ruin=false){const common=`fill="${ruin?'#c5c2ab':recon?'#b9a271':'#aa7962'}" stroke="#5b5946" stroke-width="1.5"`;let shape=type==='pilot'?`<circle cx="18" cy="18" r="13" fill="#d6e3e5" stroke="#406b76" stroke-width="2"/><path d="M12 10H24V26H12Z M10 9H26 M18 3V9 M8 29H28" fill="#eae0c4" stroke="#406b76" stroke-width="1.5"/>`:type==='castle'?`<path ${common} d="M5 5H31V30H5Z M12 12V23H24V12Z" fill-rule="evenodd"/><path d="M5 5H12V12H5Z M24 23H31V30H24Z" ${common}/>`:type==='church'?`<path ${common} d="M7 11H28V25H7Z M2 13H10V23H2Z"/><path d="M10 18H28" stroke="#705c4d"/>`:type==='fortress'?`<path ${common} d="M3 4H32V30H3V23H24V11H3Z" ${ruin?'stroke-dasharray="3 2"':''}/>`:type==='farm'?`<rect x="3" y="4" width="11" height="26" ${common}/><rect x="21" y="5" width="11" height="9" ${common}/><rect x="21" y="21" width="11" height="9" ${common}/><path d="M8 4V30" stroke="#786343"/>`:type==='hut'?`<ellipse cx="18" cy="18" rx="13" ry="10" ${common}/><path d="M6 18H30" stroke="#79633e"/>`:`<rect x="4" y="8" width="28" height="20" ${common}/><path d="M4 18H32M4 8L11 18L4 28M32 8L25 18L32 28" fill="none" stroke="#79634e"/>`;return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 36 36">${recon?'<rect x="1" y="1" width="34" height="34" rx="3" fill="none" stroke="#806640" stroke-dasharray="3 3"/>':''}${shape}</svg>`}
const iconCache=new Map();function iconFor(b){let ruin=b.id==='bomarsund'&&year>=1854,key=b.type+b.recon+ruin;if(!iconCache.has(key)){let im=new Image();im.onload=draw;im.src='data:image/svg+xml;charset=utf-8,'+encodeURIComponent(symbol(b.type,b.recon,ruin));iconCache.set(key,im)}return iconCache.get(key)}
function sourceLink(k){return `<a href="${sources[k][1]}" target="_blank" rel="noreferrer">${sources[k][0]} ↗</a>`}
